lesson('p2-t1-d01',28,'Slide so sánh AI PM với ship-and-forget. Sau khi ship sản phẩm AI, chu trình nào cần tiếp tục?', ['Chỉ lưu bản build rồi kết thúc','Monitor, eval, fallback và iterate','Chỉ tăng số tính năng','Bỏ mọi log để giảm chi phí'],'b','Sản phẩm AI có vòng lặp sau ship vì chất lượng biến thiên, drift và failure.','Theo slide, một sản phẩm AI sẽ chạy đúng thiết kế mãi mãi sau lần ship đầu tiên.',False,'Slide bác bỏ ship-and-forget và nhấn mạnh vòng lặp cải thiện.','Những hoạt động nào được nêu trong vòng lặp sau ship? (Chọn tất cả đáp án đúng.)',['Monitor','Eval và fallback','Bỏ theo dõi drift','Không bao giờ quay lại build'],['a','b'],'Monitor/eval/fallback/iterate quay lại build.')
lesson('p2-t1-d02',9,'Trong ví dụ Grab giả định, push notification khi tài xế đến thuộc loại nào?', ['Outcome cuối cùng duy nhất','Output team tạo ra','Bằng chứng chắc chắn pain đã được giải quyết','Chỉ số retention'],'b','Notification là output; outcome là nhận biết, phản ứng, tìm nhau nhanh hơn và bắt đầu chuyến sớm hơn.','Theo slide, tạo được push notification đồng nghĩa đã đo được tài xế chờ ít hơn.',False,'Output và outcome được tách biệt; phải đánh giá tác động mong muốn.','Những điều nào là outcome mong muốn của ví dụ? (Chọn tất cả đáp án đúng.)',['Hai bên tìm thấy nhau nhanh hơn','Tài xế chờ ít hơn','Chỉ số dòng code notification tăng','Có thêm một màn hình cài đặt'],['a','b'],'Các outcome tập trung vào phối hợp pickup, không phải số tính năng.')
lesson('p2-t1-d03',10,'Vì sao prototype nên kiểm tra một giả định trong một phiên?', ['Để không cần phản hồi người dùng','Để biết phản ứng đến từ thay đổi nào','Để phát hành toàn sản phẩm ngay','Để không phải đặt câu hỏi nghiên cứu'],'b','Ba thay đổi cùng lúc làm lẫn nguyên nhân phản ứng của user.','Slide khuyên đưa cả nhắc AI, thanh tiến độ và huy hiệu vào một thử nghiệm để biết chính xác tác động từng phần.',False,'Nguồn đối chiếu ba tính năng lẫn nhau với một tính năng ở một khoảnh khắc.','Những lựa chọn nào phù hợp nguyên tắc một giả định mỗi phiên? (Chọn tất cả đáp án đúng.)',['Giữ tiến độ/huy hiệu cho phiên sau','Chỉ thay đổi một cơ chế can thiệp trong khoảnh khắc đang nghiên cứu','Thay mọi thành phần cùng lúc','Dùng phản ứng chung để kết luận riêng từng tính năng'],['a','b'],'Giảm nhiễu giúp phản hồi nói đúng về can thiệp được thử.')
lesson('p2-t1-d04',10,'Trong quy trình eval mô tả trên slide, dữ liệu khởi đầu nên lấy từ đâu?', ['Chỉ từ ví dụ quảng cáo','Log và tương tác thực, gồm thumbs-down/usage','Chỉ từ benchmark model tổng quát','Tạo hàng nghìn dòng bất kỳ trước khi nhìn data'],'b','PM đọc thumbs-down/usage logs; data specialist tạo targeted dataset từ log thật.','Slide ưu tiên quality hơn quantity khi human label failures.',True,'Quality quan trọng hơn quantity được ghi ở vai trò data specialist.','Những việc nào thuộc vòng lặp eval được nêu? (Chọn tất cả đáp án đúng.)',['Curate targeted dataset','Score rồi inspect/review failures','Chỉ đổi prompt mà không xem failures','Dừng thu thập data mới sau lần đầu'],['a','b'],'Quy trình Decide–Curate–Score–Inspect quay lại cải thiện từ failure themes.')
lesson('p2-t1-d05',6,'Lớp Responsible AI chủ yếu chuyển giá trị thành điều gì theo sơ đồ?', ['Chỉ khẩu hiệu về đạo đức','Quy trình, vai trò và accountability','Chỉ model lớn hơn','Chỉ số lượng token tối đa'],'b','Responsible AI là tầng hành động/hệ vận hành biến giá trị thành process/roles/accountability.','AI Safety Evaluation trong sơ đồ đặt câu hỏi về failure, harm và ngưỡng chặn launch.',True,'Tầng kiểm tra yêu cầu bằng chứng và safeguard trước deployment.','Những mục nào thuộc lớp AI Ethics trong sơ đồ? (Chọn tất cả đáp án đúng.)',['Fairness','Human rights và transparency','Chỉ throughput GPU','Chỉ retry count'],['a','b'],'Ethics là la bàn giá trị, gồm fairness, transparency, human rights.')
lesson('p2-t1-d06',12,'Metric nào trong Measurement Ladder phù hợp tầng retention?', ['CTR/reach','D1/D7/D30 return rate','Chỉ onboarding completion','Số pixel trên màn hình'],'b','Return rate theo D1/D7/D30 đo người dùng quay lại.','Revenue như trial-to-paid/LTV thường nhìn thấy muộn hơn tín hiệu marketing/traffic trên ladder.',True,'Nguồn đặt traffic ở Day0 và revenue ở Day30–60+ muộn nhất.','Những metric nào được ghép đúng tầng? (Chọn tất cả đáp án đúng.)',['Onboarding completion → Activation','Bounce rate/session time → Visitor','CTR → Revenue','D30 return rate → Marketing traffic'],['a','b'],'Bảng ghép metric theo giai đoạn, tránh nhầm acquisition với retention/revenue.')
lesson('p2-t1-d07',12,'Vì sao mô hình unlimited token có thể gây lỗ dù đa số khách dùng ít?', ['Token API không tạo chi phí','Power user tạo cost lớn hơn khoản phí cố định','Mọi user có usage giống nhau','Giá subscription luôn bằng chi phí'],'b','Một nhóm power user đốt API lớn có thể kéo margin toàn công ty xuống.','Mô hình hybrid trong slide gồm phí gói cơ bản và trả thêm khi vượt usage cho phép.',True,'Ví dụ có quota token rồi charge theo usage phần vượt.','Những mục tiêu nào của hybrid pricing được slide nêu? (Chọn tất cả đáp án đúng.)',['Power user trả tương xứng cost tạo ra','Bảo vệ margin ở các mức sử dụng','Cho mọi usage vô hạn miễn phí','Bỏ hoàn toàn việc đo usage'],['a','b'],'Hybrid gắn mức trả với usage thay vì cố định unlimited.')
lesson('p2-t1-d08',9,'Cost/Job trong slide là gì?', ['Chỉ tổng tiền API của một tháng','Chi phí để AI làm xong một việc','Doanh thu bình quân mỗi tài khoản','Chỉ giá GPU mua ban đầu'],'b','Giá sàn dựa trên cost hoàn thành job, gồm nhiều thành phần.','Trong Cost/Job, HITL và retry là những khoản dễ bị quên nhưng cần đưa vào tính toán.',True,'Slide đánh dấu HITL/retry hay quên bên cạnh API, infra và overhead.','Những khoản nào được đưa vào Cost/Job trên slide? (Chọn tất cả đáp án đúng.)',['API token/STT/TTS','Infra/server/telephony','Chỉ số follower thương hiệu','Màu nút thanh toán'],['a','b'],'Cost/Job bao gồm API, infra, HITL, retry và overhead.')
lesson('p2-t1-d09',12,'Luật xử lý chỉ số nào đủ cụ thể theo khuôn của slide?', ['Nếu retention thấp thì xem xét lại','Nếu chỉ số vượt ngưỡng trong khoảng thời gian xác định thì thực hiện hành động cụ thể','Nếu thấy lo thì thêm quảng cáo','Chỉ ghi tên metric mà không có trigger'],'b','Luật cần metric/ngưỡng, thời lượng/cỡ mẫu, hành động và việc cấm làm.','Khuôn luật xử lý có cả phần KHÔNG THÌ để ngăn phản xạ sai.',True,'Nguồn giải thích phần cấm làm việc gì nhằm chặn phản xạ sai.','Những chi tiết nào làm luật xử lý dùng được? (Chọn tất cả đáp án đúng.)',['Ngưỡng và khoảng thời gian hoặc số khách','Hành động bắt đầu bằng động từ rõ ràng','Chỉ cụm từ xem xét lại','Không cần metric được định nghĩa'],['a','b'],'Đây là các thành phần giúp tránh phản ứng với một tuần xui.')
lesson('p2-t1-d10',9,'Stakeholder có ảnh hưởng cao nhưng quan tâm thấp được sơ đồ xếp nhóm nào?', ['Champions','Blockers/người cần thuyết phục','Supporters','Bystanders'],'b','Ma trận dùng hai trục ảnh hưởng và quan tâm; cao/thấp là nhóm cần thuyết phục.','Champions có ảnh hưởng cao và quan tâm cao theo ma trận.',True,'Nguồn đặt champions ở ô ảnh hưởng cao/quan tâm cao.','Những câu hỏi nào dùng để đặt stakeholder lên ma trận? (Chọn tất cả đáp án đúng.)',['Họ có ảnh hưởng đến kết quả không?','Họ có quan tâm đến dự án không?','Họ dùng laptop hãng gì?','Họ thích màu giao diện nào?'],['a','b'],'Hai trục phân loại là influence và interest.')
lesson('p2-t1-d11',12,'Một người biết cách dùng AI nhưng chưa thực hiện được trong công việc thực tế đang thiếu yếu tố nào trong ADKAR?', ['Awareness','Ability','Reinforcement','Chỉ Desire'],'b','Knowledge là biết cách; Ability là làm được trong thực tế.','Reinforcement nhằm duy trì hành vi mới, với phản hồi/quản lý theo sát/chỉ số phù hợp.',True,'ADKAR trên slide gắn reinforcement với duy trì hành vi mới.','Những ghép nối nào đúng theo slide ADKAR? (Chọn tất cả đáp án đúng.)',['Awareness → hiểu vì sao công việc cần thay đổi','Desire → có lý do muốn thay đổi','Knowledge → chỉ duy trì hành vi mới','Ability → chỉ hiểu lý do thay đổi'],['a','b'],'ADKAR phân biệt lý do thay đổi, mong muốn, biết cách, làm được và duy trì.')
# Two rubric scenarios with criterion-specific self-assessment boundaries.
def replace(doc,page,question,context,answer,explanation,criteria):
 idx=next(i for i,q in enumerate(a.qs) if q['id']==doc+'-q03');old=a.qs.pop(idx);a.add(doc,page,'scenario',question,answer,explanation,context=context,rubric=[x[0] for x in criteria]);q=a.qs.pop();q['id']=old['id'];
 for c,(_,full,partial,no) in zip(q['rubric'],criteria):c.update(full_credit=full,partial_credit=partial,no_credit=no)
 a.qs.insert(idx,q)
replace('p2-t1-d03',10,'Thiết kế lại phiên thử để có thể diễn giải phản hồi.','Prototype thay đồng thời AI nhắc học, huy hiệu và thanh tiến độ. User thích màn hình mới nhưng nhóm không biết thành phần nào có tác dụng.','Chỉ thử một thay đổi trong một khoảnh khắc, giữ các tính năng còn lại cho phiên sau; phản ứng mới có thể gắn với giả định đang kiểm tra.','Slide yêu cầu một phiên trả lời một giả định.', [('Tập trung một giả định','Giữ chỉ một tính năng/cơ chế thay đổi trong phiên.','Nói giảm số tính năng nhưng chưa chỉ rõ một thay đổi.','Vẫn thay cả ba cùng lúc.'),('Giải thích khả năng quy kết','Giải thích nhiều thay đổi làm lẫn nguyên nhân phản ứng và để phần còn lại cho phiên sau.','Chỉ nói dễ test hơn mà không nêu nhiễu/quy kết phản ứng.','Kết luận phản hồi chung chứng minh riêng cả ba hiệu quả.')])
replace('p2-t1-d09',12,'Viết lại nguyên tắc cảnh báo thành luật có thể hành động; có thể dùng ngưỡng giả định và phải ghi rõ là giả định.','Dashboard ghi: Nếu tỷ lệ giữ chân thấp thì xem xét lại sản phẩm.','Ví dụ giả định: nếu D30 retention dưới ngưỡng X trong hai cohort liên tiếp, dừng chiến dịch thu hút mới và điều tra onboarding; không tăng quảng cáo để bù. Cần chỉ rõ metric/ngưỡng, cửa sổ và hành động.','Nguồn yêu cầu NẾU/TRONG/THÌ/KHÔNG THÌ, tránh xem xét lại mơ hồ.', [('Định nghĩa trigger','Nêu metric, ngưỡng giả định và khoảng thời gian/cỡ mẫu.','Có metric/ngưỡng nhưng thiếu cửa sổ hoặc cỡ mẫu.','Chỉ nói thấp/cao mơ hồ.'),('Hành động và rào phản xạ','Nêu hành động cụ thể và một hành động cấm phù hợp khi trigger xuất hiện.','Chỉ có hành động cụ thể nhưng thiếu phần cấm.','Chỉ viết xem xét lại hoặc không có hành động.')])
